/**
 * @param {number[]} nums
 * @param {number} k
 * @return {number}
 */
var minRemoval = function(nums, k) {
    nums.sort((a, b) => a - b);

    let left = 0;
    let right = 0;
    let res = 0;

    while (right < nums.length) {
        if (nums[right] <= nums[left] * k) {
            res = Math.max(res, right - left + 1);
            right++;
        } else {
            left++;
        }
    }

    return nums.length - res;
};
